<script setup lang="ts">
import {externalSubscriptionSchema} from '@brightloop/shared'
interface External { id:string;name:string;amount:number;interval:string;nextRenewal:string|null;status:string;category?:string;usage?:string;importance?:number;purpose?:string;managementUrl:string;notes:string }
interface Candidate {receiptDate?:string|null;sourceUrl?:string;name:string;amount:number|null;interval:string;nextRenewal:string|null;status:string;managementUrl:string;notes:string;evidence:string;confidence:string}
const api=useApi(),toast=useToast(),route=useRoute()
const {data:gmail,refresh:refreshGmail}=await useFetch<{connected:boolean;email?:string}>('/api/gmail')
const mailBusy=ref(false),mailError=ref(''),mailSummary=ref('')
const scanned=ref(0),stopRequested=ref(false),scanCursor=ref<string|undefined>(),scanPaused=ref(false)
async function scanGmail(){
 if(mailBusy.value)return
 mailBusy.value=true;mailError.value='';stopRequested.value=false
 const resuming=scanPaused.value
 if(!resuming){scanned.value=0;candidates.value=[];scanCursor.value=undefined}
 let pageToken=scanCursor.value
 const found=new Map<string,Candidate>(candidates.value.map(c=>[c.name.toLowerCase(),c]))
 try{
  do{
   const result=await api<{candidates:Candidate[];scanned:number;nextPageToken:string|null}>('/gmail/scan',{method:'POST',body:{pageToken}})
   scanned.value+=result.scanned
   for(const c of result.candidates){const id=c.name.toLowerCase();const previous=found.get(id);if(!previous||Date.parse(c.receiptDate||'')>Date.parse(previous.receiptDate||''))found.set(id,c)}
   candidates.value=[...found.values()]
   pageToken=result.nextPageToken||undefined;scanCursor.value=pageToken;scanPaused.value=!!pageToken
   mailSummary.value=`${scanned.value.toLocaleString()} emails checked · ${found.size} subscription suggestions found.`
  }while(pageToken&&!stopRequested.value)
  mailSummary.value+=pageToken?' Scan stopped.':' Scan complete.';if(found.size)discoveriesOpen.value=true
 }catch(e){scanPaused.value=true;mailError.value=errorMessage(e);mailSummary.value=`Scan paused after ${scanned.value.toLocaleString()} emails. ${candidates.value.length} discoveries kept.`}finally{mailBusy.value=false}
}
function restartScan(){if(mailBusy.value)return;scanPaused.value=false;scanCursor.value=undefined;void scanGmail()}
onBeforeUnmount(()=>{stopRequested.value=true})
async function disconnectGmail(){mailBusy.value=true;try{await api('/gmail',{method:'DELETE'});await refreshGmail();candidates.value=[];mailSummary.value='';scanCursor.value=undefined;scanPaused.value=false;scanned.value=0}catch(e){mailError.value=errorMessage(e)}finally{mailBusy.value=false}}
onMounted(()=>{if(route.query.gmail_connected==='1'){void scanGmail();navigateTo('/portal',{replace:true})}if(route.query.gmail_error)mailError.value=route.query.gmail_error==='account'?'Choose the same Google account used for your Brightloop login.':'Gmail access wasn’t granted. Reconnect and approve read access to continue.'})
const {data,error,status,refresh}=await useFetch<{items:External[];totals:{monthly:number;yearly:number;active:number}}>('/api/external-subscriptions')
const open=ref(false),editing=ref(''),busy=ref(false),formError=ref('')
const mode=ref<'details'|'edit'|'review'>('edit'),selected=ref<External|null>(null),discoveriesOpen=ref(false),connectionOpen=ref(false),detailsExpanded=ref(false),search=ref(''),filter=ref('all')
const visible=computed(()=>{const now=Date.now();return (data.value?.items||[]).filter(i=>(!search.value||i.name.toLowerCase().includes(search.value.toLowerCase()))&&(filter.value==='all'||filter.value==='active'&&i.status==='ACTIVE'||filter.value==='planned'&&(i.status==='PLANNED'||i.status==='INTERESTED')||filter.value==='inactive'&&(i.status==='INACTIVE'||i.status==='CANCELLED')||filter.value==='upcoming'&&i.status==='ACTIVE'&&i.nextRenewal&&Date.parse(i.nextRenewal)<=now+7*86400000))})
const nextRenewal=computed(()=>(data.value?.items||[]).filter(i=>i.status==='ACTIVE').sort((a,b)=>Date.parse(a.nextRenewal||'')-Date.parse(b.nextRenewal||''))[0])
const filters=[{label:'All',value:'all'},{label:'Upcoming',value:'upcoming'},{label:'Active',value:'active'},{label:'Planned / Interested',value:'planned'},{label:'Inactive',value:'inactive'}]
const statusLabel=(s:string)=>({ACTIVE:'Active',PLANNED:'Planned',INTERESTED:'Interested',INACTIVE:'Inactive',CANCELLED:'Inactive'} as Record<string,string>)[s]||s
function inspect(item:External){selected.value=item;mode.value='details';open.value=true}
const empty=()=>({name:'',amount:'',interval:'MONTHLY',nextRenewal:new Date().toISOString().slice(0,10),status:'ACTIVE',category:'Other',usage:'UNKNOWN',importance:3,purpose:'',managementUrl:'',notes:''})
const form=ref(empty())
const reviewSource=ref<Candidate|null>(null)
function edit(item?:External){reviewSource.value=null;mode.value='edit';detailsExpanded.value=false;editing.value=item?.id||'';formError.value='';form.value=item?{name:item.name,amount:String(item.amount/100),interval:item.interval,nextRenewal:item.nextRenewal?.slice(0,10)||'',status:item.status,category:item.category||'Other',usage:item.usage||'UNKNOWN',importance:item.importance??3,purpose:item.purpose||'',managementUrl:item.managementUrl,notes:item.notes}:empty();open.value=true}
function skipDiscovery(){if(reviewSource.value)candidates.value=candidates.value.filter(c=>c.name!==reviewSource.value!.name);open.value=false;if(candidates.value.length)discoveriesOpen.value=true}
function review(c:Candidate){reviewSource.value=c;mode.value='review';detailsExpanded.value=false;discoveriesOpen.value=false;const existing=data.value?.items.find(i=>i.name.toLowerCase()===c.name.toLowerCase());editing.value=existing?.id||'';formError.value='';form.value={...empty(),name:c.name,interval:c.interval,nextRenewal:c.nextRenewal||'',amount:c.amount==null?(existing?String(existing.amount/100):''):String(c.amount),status:existing?.status||c.status,category:existing?.category||'Other',usage:existing?.usage||'UNKNOWN',importance:existing?.importance??3,purpose:existing?.purpose||'',managementUrl:c.managementUrl,notes:existing?.notes||c.notes};open.value=true}
async function save(){busy.value=true;formError.value='';try{const parsed=externalSubscriptionSchema.safeParse(form.value);if(!parsed.success){formError.value=parsed.error.issues.map(i=>i.message).join('; ');return}await api(`/external-subscriptions${editing.value?'/'+editing.value:''}`,{method:editing.value?'PUT':'POST',body:form.value});open.value=false;candidates.value=candidates.value.filter(c=>c.name!==form.value.name);await refresh();toast.add({title:editing.value?'Subscription updated':'Subscription added',color:'success'});if(mode.value==='review'&&candidates.value.length)discoveriesOpen.value=true}catch(e){formError.value=errorMessage(e)}finally{busy.value=false}}
const removing=ref<External|null>(null)
async function remove(){if(!removing.value)return;busy.value=true;try{await api(`/external-subscriptions/${removing.value.id}`,{method:'DELETE'});removing.value=null;open.value=false;await refresh()}catch(e){toast.add({title:errorMessage(e),color:'error'})}finally{busy.value=false}}
const candidates=ref<Candidate[]>([])
const due=computed(()=>data.value?.items.filter(i=>i.status==='ACTIVE'&&Date.parse(i.nextRenewal||'')<=Date.now()+7*86400000)||[])
function renewalLabel(value:string|null){if(!value)return 'Date not set';const days=Math.ceil((Date.parse(value)-Date.now())/86400000);return days<0?'Date passed — review renewal':days===0?'Renews today':`Renews in ${days} day${days===1?'':'s'}`}
</script>
<template>
 <div class="page space-y-6">
  <div class="flex flex-wrap justify-between items-start gap-4">
   <div><h1 class="text-2xl font-semibold tracking-tight">Your subscriptions, in one place.</h1><p class="text-sm text-muted mt-2">See what you pay for and stay ahead of the next renewal.</p></div>
   <div class="flex items-center gap-2"><UButton color="neutral" variant="outline" icon="i-lucide-plug" @click="connectionOpen=true">{{gmail?.connected?'Gmail connected':'Connections'}}</UButton><UButton v-if="data?.items.length" color="neutral" variant="outline" icon="i-lucide-plus" @click="edit()">Add subscription</UButton><UButton v-if="gmail?.connected" icon="i-lucide-scan-search" :loading="mailBusy" @click="scanGmail">{{scanPaused?'Resume scan':'Find subscriptions'}}</UButton></div>
  </div>
  <UAlert v-if="error" color="error" :title="errorMessage(error)"><template #actions><UButton @click="refresh()">Try again</UButton></template></UAlert>
  <UAlert v-if="mailError" color="error" :title="mailError"><template #actions><UButton :loading="mailBusy" @click="scanGmail">Resume scan</UButton><UButton color="neutral" variant="ghost" @click="connectionOpen=true">Connection settings</UButton></template></UAlert>
  <UCard v-if="mailBusy" :ui="{body:'space-y-3'}"><div class="flex justify-between items-center gap-4"><div class="flex gap-3 items-center"><UIcon name="i-lucide-loader-circle" class="size-5 animate-spin text-primary"/><div><p class="text-sm font-medium">Finding your subscriptions</p><p class="text-xs text-muted mt-1">{{scanned.toLocaleString()}} emails checked · {{candidates.length}} discoveries</p></div></div><UButton color="neutral" variant="ghost" :disabled="stopRequested" @click="stopRequested=true">{{stopRequested?'Stopping…':'Stop scan'}}</UButton></div><UProgress size="xs"/></UCard>
  <div v-else-if="candidates.length" class="flex flex-wrap items-center justify-between gap-4 rounded-lg border border-primary/25 bg-primary/5 px-5 py-4"><div class="flex items-center gap-3"><span class="flex p-2 rounded-full bg-primary/10 text-primary"><UIcon name="i-lucide-sparkles" class="size-5"/></span><div><p class="text-sm font-semibold">{{candidates.length}} discoveries ready to review</p><p class="text-xs text-muted mt-1">Check the price and renewal date before adding them.</p></div></div><UButton trailing-icon="i-lucide-arrow-right" @click="discoveriesOpen=true">Review discoveries</UButton></div>
  <UCard v-if="!data?.items.length && status!=='pending' && !error && !mailBusy && !candidates.length" :ui="{body:'!p-0'}">
   <div class="max-w-xl mx-auto px-6 py-14 sm:py-20 text-center"><div class="flex justify-center mb-6"><span class="p-4 rounded-2xl bg-primary/10 ring ring-primary/20"><UIcon :name="gmail?.connected?'i-lucide-scan-search':'i-lucide-mail'" class="size-8 text-primary"/></span></div><UBadge variant="subtle" color="neutral" class="mb-4">{{gmail?.connected?'Ready to discover':'Get started'}}</UBadge><h2 class="text-2xl font-semibold tracking-tight">{{gmail?.connected?'Let’s find what you’re subscribed to.':'Start with your inbox.'}}</h2><p class="text-sm leading-6 text-muted mt-3 max-w-md mx-auto">{{gmail?.connected?'Scan your receipts, review what we find, and build a clear picture of your recurring spending.':'Connect Gmail to find subscription receipts. You choose what to keep—we’ll help you track the cost and the next renewal.'}}</p><UButton v-if="!gmail?.connected" to="/api/auth/google?gmail=1" external icon="i-lucide-mail" size="lg" class="mt-7">Connect Gmail</UButton><UButton v-else icon="i-lucide-scan-search" size="lg" class="mt-7" @click="scanGmail">Find my subscriptions</UButton><div class="mt-4"><UButton variant="link" color="neutral" size="sm" @click="edit()">Add a subscription manually</UButton></div><div class="grid grid-cols-3 gap-4 mt-12 pt-6 border-t border-default"><div v-for="(step,i) in ['Connect your inbox','Review discoveries','Stay on top of renewals']" :key="step"><span class="inline-flex size-6 items-center justify-center rounded-full bg-elevated text-xs text-muted">{{i+1}}</span><p class="text-xs text-muted mt-2">{{step}}</p></div></div><p class="text-[11px] text-dimmed mt-6">Read-only access. We never send, edit, or delete your emails.</p></div>
  </UCard>
  <template v-if="data?.items.length || status==='pending'">
   <div class="grid sm:grid-cols-3 gap-px rounded-lg border border-default bg-default overflow-hidden"><div class="p-5 sm:p-6 bg-elevated/25"><p class="text-xs text-muted uppercase tracking-wide">Monthly spending</p><USkeleton v-if="status==='pending'" class="h-8 w-28 mt-3"/><p v-else class="text-2xl font-semibold mt-3 tabular-nums">{{money(data?.totals.monthly)}}</p><p class="text-xs text-dimmed mt-1">{{data?.totals.active||0}} active subscriptions</p></div><div class="p-5 sm:p-6 bg-elevated/25 sm:border-x border-default"><p class="text-xs text-muted uppercase tracking-wide">Yearly estimate</p><p class="text-2xl font-semibold mt-3 tabular-nums">{{money(data?.totals.yearly)}}</p><p class="text-xs text-dimmed mt-1">Based on current active plans</p></div><div class="p-5 sm:p-6 bg-elevated/25"><p class="text-xs text-muted uppercase tracking-wide">Next renewal</p><p class="text-2xl font-semibold mt-3">{{nextRenewal?date(nextRenewal.nextRenewal):'—'}}</p><p class="text-xs text-dimmed mt-1">{{nextRenewal?`${nextRenewal.name} · ${money(nextRenewal.amount)}`:'No upcoming renewals'}}</p></div></div>
   <div class="rounded-lg border border-default overflow-hidden"><div class="flex flex-wrap justify-between items-center gap-3 p-4 border-b border-default"><div class="flex gap-1 flex-wrap"><UButton v-for="tab in filters" :key="tab.value" :color="filter===tab.value?'primary':'neutral'" :variant="filter===tab.value?'soft':'ghost'" size="sm" @click="filter=tab.value">{{tab.label}}<UBadge v-if="tab.value==='upcoming'&&due.length" size="xs" color="neutral" variant="subtle">{{due.length}}</UBadge></UButton></div><UInput v-model="search" icon="i-lucide-search" placeholder="Search subscriptions" aria-label="Search subscriptions" class="w-full sm:w-56"/></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-elevated/25 text-muted text-left"><tr><th class="px-5 py-3 font-medium">Subscription</th><th class="px-5 py-3 font-medium">Amount</th><th class="px-5 py-3 font-medium hidden sm:table-cell">Next renewal</th><th class="px-5 py-3 font-medium hidden md:table-cell">Status</th><th class="px-5 py-3"><span class="sr-only">Manage</span></th></tr></thead><tbody class="divide-y divide-default"><tr v-for="item in visible" :key="item.id" class="hover:bg-elevated/40 transition-colors"><td class="px-5 py-4"><button class="flex items-center gap-3 text-left rounded focus-visible:outline-primary" @click="inspect(item)"><UAvatar :alt="item.name" size="md" class="ring ring-default rounded-lg"/><div><p class="font-medium text-highlighted">{{item.name}}</p><p class="text-xs text-muted mt-1 capitalize">{{item.interval.toLowerCase()}} plan</p></div></button></td><td class="px-5 py-4 font-medium whitespace-nowrap">{{money(item.amount)}}</td><td class="px-5 py-4 hidden sm:table-cell"><p>{{date(item.nextRenewal)}}</p><p v-if="item.status==='ACTIVE'" class="text-xs text-muted mt-1">{{renewalLabel(item.nextRenewal)}}</p></td><td class="px-5 py-4 hidden md:table-cell"><UBadge :color="item.status==='ACTIVE'?'success':'neutral'" variant="subtle" size="sm">{{statusLabel(item.status)}}</UBadge></td><td class="px-5 py-4 text-right"><UButton color="neutral" variant="ghost" icon="i-lucide-chevron-right" :aria-label="`Manage ${item.name}`" @click="inspect(item)"/></td></tr></tbody></table><div v-if="!visible.length" class="py-14 text-center"><UIcon name="i-lucide-search" class="size-6 text-dimmed"/><p class="text-sm text-muted mt-3">No subscriptions match this view.</p><UButton variant="link" size="sm" @click="search='';filter='all'">Clear filters</UButton></div></div></div>
  </template>
  <p v-if="mailSummary&&!mailBusy" class="text-xs text-dimmed flex gap-2 items-center"><UIcon :name="scanPaused?'i-lucide-pause':'i-lucide-circle-check'"/>{{mailSummary}}</p>
  <USlideover v-model:open="open" :title="mode==='details'?(selected?.name||'Subscription'):mode==='review'?'Review discovery':editing?'Edit subscription':'Add subscription'" :description="mode==='details'?'Your plan, payments and renewal details.':mode==='review'?'Confirm the details before adding this subscription.':'Keep your plan details up to date.'" :ui="{footer:'block'}">
   <template #body>
    <div v-if="mode==='details'&&selected" class="space-y-7"><div class="flex items-center gap-4"><UAvatar :alt="selected.name" size="xl" class="rounded-xl ring ring-default"/><div><p class="text-3xl font-semibold">{{money(selected.amount)}}</p><p class="text-sm text-muted capitalize mt-1">Billed {{selected.interval.toLowerCase()}}</p></div></div><div class="divide-y divide-default"><div class="flex justify-between py-4"><span class="text-sm text-muted">Status</span><UBadge :color="selected.status==='ACTIVE'?'success':'neutral'" variant="subtle">{{statusLabel(selected.status)}}</UBadge></div><div class="flex justify-between py-4"><span class="text-sm text-muted">Next renewal</span><span class="text-sm font-medium">{{date(selected.nextRenewal)}}</span></div><div v-if="selected.status==='ACTIVE'" class="flex justify-between py-4"><span class="text-sm text-muted">Coming up</span><span class="text-sm">{{renewalLabel(selected.nextRenewal)}}</span></div></div><div v-if="selected.notes"><p class="text-sm font-medium mb-2">Notes</p><p class="text-sm text-muted whitespace-pre-wrap">{{selected.notes}}</p></div><UButton v-if="selected.managementUrl" :to="selected.managementUrl" target="_blank" external rel="noopener noreferrer" block trailing-icon="i-lucide-external-link">Manage with {{selected.name}}</UButton><p class="text-xs text-dimmed leading-5">To change or cancel your plan, visit the provider. Update your record here after making changes.</p></div>
    <form v-else id="subscription-form" class="space-y-5" @submit.prevent="save"><UAlert v-if="formError" color="error" :title="formError"/><div v-if="mode==='review'&&reviewSource" class="rounded-lg bg-elevated/50 p-4 space-y-2"><div class="flex gap-2 items-center text-sm font-medium"><UIcon name="i-lucide-mail" class="text-primary"/>Found in your inbox</div><p class="text-xs text-muted leading-5">{{reviewSource.evidence}}</p><UButton v-if="reviewSource.sourceUrl" :to="reviewSource.sourceUrl" external target="_blank" rel="noopener noreferrer" variant="link" size="xs" class="px-0" trailing-icon="i-lucide-external-link">Open original receipt</UButton></div><UFormField label="Subscription name" required><UInput v-model="form.name" placeholder="e.g. Netflix" class="w-full" autofocus/></UFormField><div class="grid grid-cols-2 gap-4"><UFormField label="Amount (₹)" required><UInput v-model="form.amount" type="number" min="0" step="0.01" placeholder="0.00" class="w-full"/></UFormField><UFormField label="Billing cycle"><USelect v-model="form.interval" :items="[{label:'Monthly',value:'MONTHLY'},{label:'Yearly',value:'YEARLY'},{label:'Weekly',value:'WEEKLY'}]" class="w-full"/></UFormField></div><UFormField label="Next renewal" :required="form.status==='ACTIVE'" :help="form.status==='ACTIVE'?'Required for active services.':'Not needed unless active.'"><UInput v-model="form.nextRenewal" type="date" class="w-full"/></UFormField><UFormField label="Status" help="Planned and interested services do not count as active spending."><USelect v-model="form.status" :items="[{label:'Active',value:'ACTIVE'},{label:'Planned',value:'PLANNED'},{label:'Interested',value:'INTERESTED'},{label:'Inactive',value:'INACTIVE'}]" class="w-full"/></UFormField><div class="grid grid-cols-2 gap-4"><UFormField label="Category"><USelect v-model="form.category" :items="['Entertainment','AI','Education','Productivity','Development','Cloud','Design','Gaming','Music','Lifestyle','Other'].map(c=>({label:c,value:c}))" class="w-full"/></UFormField><UFormField label="Expected usage" help="Self-reported — receipts cannot prove use."><USelect v-model="form.usage" :items="[{label:'Not sure',value:'UNKNOWN'},{label:'High',value:'HIGH'},{label:'Medium',value:'MEDIUM'},{label:'Low',value:'LOW'}]" class="w-full"/></UFormField></div><div class="grid grid-cols-2 gap-4"><UFormField label="Importance (1–5)"><UInput v-model.number="form.importance" type="number" min="1" max="5" class="w-full"/></UFormField><UFormField label="Purpose"><UInput v-model="form.purpose" placeholder="Why you keep it" class="w-full"/></UFormField></div><UCollapsible v-model:open="detailsExpanded"><UButton color="neutral" variant="ghost" trailing-icon="i-lucide-chevron-down" class="px-0">Additional details</UButton><template #content><div class="space-y-4 pt-3"><UFormField label="Management link" help="An HTTPS link to your account with the provider."><UInput v-model="form.managementUrl" type="url" placeholder="https://" class="w-full"/></UFormField><UFormField label="Notes"><UTextarea v-model="form.notes" class="w-full" placeholder="Anything you want to remember"/></UFormField></div></template></UCollapsible></form>
   </template>
   <template #footer><div v-if="mode==='details'" class="flex justify-between w-full"><UButton color="error" variant="ghost" @click="removing=selected">Remove record</UButton><UButton icon="i-lucide-pencil" @click="edit(selected||undefined)">Edit details</UButton></div><div v-else class="flex justify-end gap-2"><UButton v-if="mode==='review'" color="neutral" variant="ghost" @click="skipDiscovery">Skip discovery</UButton><UButton v-else color="neutral" variant="ghost" @click="open=false">Cancel</UButton><UButton type="submit" form="subscription-form" :loading="busy">{{editing?'Save changes':'Add subscription'}}</UButton></div></template>
  </USlideover>
  <USlideover v-model:open="discoveriesOpen" title="Discoveries" :description="`${candidates.length} subscriptions to review. Nothing is saved until you confirm.`"><template #body><div class="space-y-3"><button v-for="candidate in candidates" :key="candidate.name" class="w-full rounded-lg border border-default hover:bg-elevated/50 p-4 text-left flex items-center gap-3 transition-colors" @click="review(candidate)"><UAvatar :alt="candidate.name" class="rounded-lg"/><div class="flex-1 min-w-0"><p class="font-medium text-sm truncate">{{candidate.name}}</p><p class="text-xs text-muted mt-1">{{candidate.amount==null?'Price needs confirmation':money(candidate.amount*100)}} · {{data?.items.some(i=>i.name.toLowerCase()===candidate.name.toLowerCase())?'Update existing':'New discovery'}}</p></div><UIcon name="i-lucide-chevron-right" class="text-dimmed"/></button><div v-if="!candidates.length" class="text-center py-16"><UIcon name="i-lucide-circle-check" class="size-8 text-primary"/><p class="text-sm text-muted mt-3">All discoveries reviewed.</p></div></div></template></USlideover>
  <UModal v-model:open="connectionOpen" title="Gmail connection" description="Discover subscriptions from your own inbox."><template #body><div class="space-y-5"><div class="flex items-center gap-3 rounded-lg border border-default p-4"><span class="p-2 rounded-lg bg-elevated flex"><UIcon name="i-lucide-mail" class="size-5"/></span><div class="flex-1 min-w-0"><p class="font-medium text-sm">{{gmail?.connected?gmail.email:'Gmail'}}</p><p class="text-xs text-muted mt-1">{{gmail?.connected?'Connected · read-only access':'Not connected'}}</p></div><UIcon v-if="gmail?.connected" name="i-lucide-circle-check" class="text-primary size-5"/></div><p class="text-sm text-muted leading-6">Brightloop checks email senders, subjects and previews for subscription receipts. You review discoveries before saving them. We never send, edit or delete your emails.</p><UButton v-if="!gmail?.connected" to="/api/auth/google?gmail=1" external block icon="i-lucide-mail">Connect Gmail</UButton><div v-else class="flex justify-between items-center"><div class="flex gap-2"><UButton to="/api/auth/google?gmail=1" external color="neutral" variant="outline">Reconnect</UButton><UButton v-if="scanPaused" color="neutral" variant="ghost" :disabled="mailBusy" @click="connectionOpen=false;restartScan()">Start fresh scan</UButton></div><UButton color="error" variant="ghost" :disabled="mailBusy" @click="disconnectGmail">Disconnect</UButton></div><UAlert v-if="mailError" color="error" :title="mailError"/></div></template></UModal>
  <UModal :open="!!removing" title="Remove this subscription?" description="This removes the record from your dashboard. Your plan with the provider stays unchanged." @update:open="value=>{if(!value)removing=null}"><template #footer><UButton color="neutral" variant="outline" @click="removing=null">Keep subscription</UButton><UButton color="error" :loading="busy" @click="remove">Remove record</UButton></template></UModal>
 </div>
</template>
